<?php
namespace App\Services\Enterprise;
use App\Models\{EnterpriseIdentityProvider,EnterpriseSsoState,Role,User,WorkspaceMember};use App\Services\Security\OutboundUrlGuard;use App\Services\Security\SecurityEventService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
/** Provides oidc service behavior within the WorkIntel application. */ class OidcService{
 /** Initializes the class with its required dependencies and state. */ public function __construct(private readonly OutboundUrlGuard $guard){}
 /** Handles the provider config operation for the current WorkIntel workflow. */ public function providerConfig(EnterpriseIdentityProvider $provider):array{return json_decode(Crypt::decryptString($provider->config_encrypted),true)?:[];}
 /** Handles the authorization url operation for the current WorkIntel workflow. */ public function authorizationUrl(EnterpriseIdentityProvider $provider):string{abort_unless($provider->type==='oidc'&&$provider->status==='active',404);$c=$this->providerConfig($provider);foreach(['client_id','authorization_endpoint','token_endpoint','userinfo_endpoint'] as $k)abort_unless(filled($c[$k]??null),422,"OIDC provider is missing {$k}.");$this->guard->assertSafe($c['authorization_endpoint']);$state=Str::random(64);$verifier=Str::random(96);$nonce=Str::random(40);$challenge=rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'=');$redirect=route('enterprise.oidc.callback',['provider'=>$provider->id]);EnterpriseSsoState::create(['state_hash'=>hash('sha256',$state),'enterprise_identity_provider_id'=>$provider->id,'code_verifier_encrypted'=>Crypt::encryptString($verifier),'nonce'=>$nonce,'redirect_uri'=>$redirect,'expires_at'=>now()->addMinutes(10),'created_at'=>now()]);$query=http_build_query(['client_id'=>$c['client_id'],'response_type'=>'code','redirect_uri'=>$redirect,'scope'=>$c['scopes']??'openid email profile','state'=>$state,'nonce'=>$nonce,'code_challenge'=>$challenge,'code_challenge_method'=>'S256']);return rtrim($c['authorization_endpoint'],'?').'?'.$query;}
 /** Handles the callback operation for the current WorkIntel workflow. */ public function callback(EnterpriseIdentityProvider $provider,Request $request):User{abort_unless($provider->type==='oidc'&&$provider->status==='active',404);$state=(string)$request->query('state');$code=(string)$request->query('code');abort_unless($state&&$code,422,'OIDC callback is missing state or authorization code.');$row=EnterpriseSsoState::where('state_hash',hash('sha256',$state))->where('enterprise_identity_provider_id',$provider->id)->first();abort_unless($row&&$row->expires_at->isFuture(),422,'OIDC state is invalid or expired.');$c=$this->providerConfig($provider);$this->guard->assertSafe($c['token_endpoint']);$this->guard->assertSafe($c['userinfo_endpoint']);$verifier=Crypt::decryptString($row->code_verifier_encrypted);$redirectUri=$row->redirect_uri;$row->delete();$tokenReq=['grant_type'=>'authorization_code','code'=>$code,'redirect_uri'=>$redirectUri,'client_id'=>$c['client_id'],'code_verifier'=>$verifier];if(filled($c['client_secret']??null))$tokenReq['client_secret']=$c['client_secret'];$token=Http::asForm()->timeout(12)->post($c['token_endpoint'],$tokenReq);abort_unless($token->successful()&&filled($token->json('access_token')),422,'OIDC token exchange failed.');$info=Http::withToken($token->json('access_token'))->acceptJson()->timeout(12)->get($c['userinfo_endpoint']);abort_unless($info->successful(),422,'OIDC user info request failed.');$profile=$info->json();$email=strtolower((string)($profile['email']??''));abort_unless(filter_var($email,FILTER_VALIDATE_EMAIL),422,'OIDC provider did not return a valid email address.');abort_if(($profile['email_verified']??true)===false,422,'OIDC email address is not verified.');$domains=$provider->domains??[];if($domains){$domain=strtolower(substr(strrchr($email,'@')?:'',1));abort_unless(in_array($domain,array_map('strtolower',$domains),true),403,'Your email domain is not allowed for this identity provider.');}$workspace=$provider->workspace_id;$user=User::where('email',$email)->first();if(!$user){abort_unless($provider->jit_provisioning,403,'No WorkIntel user exists for this SSO identity.');$names=$this->names($profile);$user=User::create(['first_name'=>$names[0],'last_name'=>$names[1],'email'=>$email,'password'=>Hash::make(Str::random(64)),'timezone'=>'UTC','status'=>'active']);}$member=WorkspaceMember::where('workspace_id',$workspace)->where('user_id',$user->id)->where('status','active')->first();if(!$member){abort_unless($provider->jit_provisioning,403,'This SSO user is not a member of the workspace.');$member=WorkspaceMember::create(['workspace_id'=>$workspace,'user_id'=>$user->id,'job_title'=>'SSO User','employment_type'=>'full_time','employment_stage'=>'active','joining_date'=>today(),'status'=>'active','timezone'=>$user->timezone]);$role=Role::where('workspace_id',$workspace)->where('status','active')->where('slug',$provider->default_role_slug)->first()?:Role::where('workspace_id',$workspace)->where('status','active')->where('slug','employee')->first();if($role)$member->roles()->sync([$role->id]);}Auth::login($user);if($request->hasSession()){$request->session()->regenerate();$request->session()->put('enterprise_sso_workspace_id',(int)$workspace);if(($c['trust_idp_mfa']??false))$request->session()->put('mfa_verified_at',now()->toIso8601String());}$user->forceFill(['last_login_at'=>now()])->save();app(SecurityEventService::class)->record($member->workspace,$user,'auth.sso_login_succeeded','info',$request,['provider_id'=>$provider->id,'provider_type'=>'oidc']);return $user;}
 /** Handles the test operation for the current WorkIntel workflow. */ public function test(EnterpriseIdentityProvider $provider):array{$c=$this->providerConfig($provider);if($provider->type==='saml')return ['ok'=>true,'runtime'=>'configuration_only','message'=>'SAML metadata/configuration is valid at the WorkIntel layer. Signed assertion runtime requires a standards-compliant SAML adapter.'];$endpoint=$c['issuer']??null;if($endpoint){$url=rtrim($endpoint,'/').'/.well-known/openid-configuration';$this->guard->assertSafe($url);$r=Http::acceptJson()->timeout(8)->get($url);return ['ok'=>$r->successful(),'status'=>$r->status(),'issuer'=>$r->json('issuer'),'authorization_endpoint'=>$r->json('authorization_endpoint')];}foreach(['authorization_endpoint','token_endpoint','userinfo_endpoint'] as $k){abort_unless(filled($c[$k]??null),422,"Missing {$k}");$this->guard->assertSafe($c[$k]);}return ['ok'=>true,'message'=>'OIDC endpoints passed URL safety validation.'];}
 /** Handles the names operation for the current WorkIntel workflow. */ private function names(array $p):array{$first=trim((string)($p['given_name']??''));$last=trim((string)($p['family_name']??''));if(!$first){$parts=preg_split('/\s+/',trim((string)($p['name']??'SSO User')));$first=array_shift($parts)?:'SSO';$last=implode(' ',$parts)?:'User';}return [$first,$last?:'User'];}
}
